  static void Seat(GameObject g){var b=WorldBounds(g);float y=float.MaxValue;foreach(float x in new[]{b.min.x,b.center.x,b.max.x})foreach(float z in new[]{b.min.z,b.center.z,b.max.z})y=Mathf.Min(y,Ground(new Vector3(x,0,z)));g.transform.position+=Vector3.up*(y-b.min.y-.025f);}
