  static void Quad(List<Vector3> v,List<int> ix,Vector3 a,Vector3 b,Vector3 c,Vector3 d){int k=v.Count;v.AddRange(new[]{a,b,c,d});ix.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}
