  static void Road(Route route,bool lines=true){var v=new List<Vector3>();var ix=new List<int>();var lv=new List<Vector3>();var li=new List<int>();float walked=0;var pts=route.points.Select(p=>p.V).ToArray();Vector3 Surface(Vector3 p,float y=.09f){p.y=Ground(p)+y;return p;}Vector3 Side(int i){var dir=pts[Mathf.Min(i+1,pts.Length-1)]-pts[Mathf.Max(i-1,0)];return Vector3.Cross(Vector3.up,dir.normalized);}
   for(int i=0;i<pts.Length-1;i++){var a=pts[i];var b=pts[i+1];float length=Vector3.Distance(a,b);if(length<.0001f)continue;var sa=Side(i);var sb=Side(i+1);int columns=Mathf.CeilToInt(route.width/2);for(int j=0;j<columns;j++){float u=j/(float)columns*2-1,w=(j+1f)/columns*2-1;Quad(v,ix,Surface(a+sa*u*route.width*.5f),Surface(b+sb*u*route.width*.5f),Surface(b+sb*w*route.width*.5f),Surface(a+sa*w*route.width*.5f));}if(lines&&walked%8<2.5f&&length>.25f){var forward=(b-a).normalized;var end=a+forward*Mathf.Min(1.5f,length);Quad(lv,li,Surface(a-sa*.075f,.105f),Surface(end-sa*.075f,.105f),Surface(end+sa*.075f,.105f),Surface(a+sa*.075f,.105f));}walked+=length;}
   Display(route.name,roads,SaveMesh(route.name,v,ix),asphalt,true);if(lv.Count>0)Display(route.name+" | yellow centre dashes",roads,SaveMesh("Yellow centre markings",lv,li),marking,false);
  }
  static void Pad(string name,Vector3 centre,float width,float depth){Road(new Route{name=name,width=width,points=new[]{new Point{x=centre.x,z=centre.z-depth*.5f},new Point{x=centre.x,z=centre.z+depth*.5f}}},false);}
  static float EdgeMaximum(Terrain t){var d=t.terrainData;return Enumerable.Range(0,101).SelectMany(i=>new[]{d.GetInterpolatedHeight(i/100f,0),d.GetInterpolatedHeight(i/100f,1),d.GetInterpolatedHeight(0,i/100f),d.GetInterpolatedHeight(1,i/100f)}).Max()+t.transform.position.y;}
  static Terrain Terrain(PrototypeSession session,float edgeTop){float scale=(edgeTop-SnowField.Ground)/270.5157776f;var g=Instance("TerrainBase",terrainGroup,"Terrain | supplied 1000m mesh, vertical cut boundary",new Vector3(0,SnowField.Ground-35*scale,0));g.transform.localScale=new Vector3(1,scale,1);var f=g.GetComponentInChildren<MeshFilter>();terrainMesh=f.gameObject.AddComponent<MeshCollider>();terrainMesh.sharedMesh=f.sharedMesh;
   var d=new TerrainData{heightmapResolution=257,size=new Vector3(1000,140,1000)};var heights=new float[257,257];using(var reader=new BinaryReader(File.OpenRead("SourceAssets/AlpsRebuild/TerrainHeight_257_f32le.raw")))for(int z=0;z<257;z++)for(int x=0;x<257;x++)heights[z,x]=(SnowField.Ground+reader.ReadSingle()*scale)/140;d.SetHeights(0,0,heights);AssetDatabase.CreateAsset(d,Root+"/TerrainQuery.asset");var query=UnityEngine.Terrain.CreateTerrainGameObject(d);query.name="Terrain height queries | source shape, rendering/collision off";query.transform.SetParent(terrainGroup,false);query.transform.position=new Vector3(-500,0,-500);var t=query.GetComponent<Terrain>();t.drawHeightmap=false;t.drawTreesAndFoliage=false;query.GetComponent<TerrainCollider>().enabled=false;session.CameraRig.terrain=t;Physics.SyncTransforms();Check(Mathf.Abs(Ground(Vector3.zero)-SnowField.Ground)<.02f,"flat snow datum");File.WriteAllText(Log+"/Terrain.txt","Original 5600-triangle mesh and vertical wall topology retained. Uniform Y relief factor "+scale+"; outer maximum "+edgeTop+"m matched to Pinefall. Flat centre "+SnowField.Ground+"m. Hidden 257 TerrainData answers existing camera height queries; physical collision is the supplied mesh. No square skirt or down-curved edge added.\n");return t;
  }
  static void Mountains(){for(int i=0;i<16;i++){float a=(i*22.5f+8)*Mathf.Deg2Rad;string slug="Mountain_"+(i%8+1).ToString("D2");var entry=AlpsRebuildAssets.Find(slug);float target=125+(i%3)*12;float scale=target/Mathf.Max(entry.localBounds.size.x,entry.localBounds.size.z);var p=new Vector3(Mathf.Sin(a)*420,0,Mathf.Cos(a)*420);var g=Instance(slug,mountains,"Mountain "+(i+1).ToString("D2")+" | "+slug,p,i*37%360,scale);NaturalMountain(g,Root);}}
  static string NaturalMountain(GameObject g,string folder){
   var placement=g.GetComponent<CatalogPlacement>();var entry=CatalogPreparation.Library().Find(placement.assetId);var src=entry.prefab.GetComponentInChildren<MeshFilter>();var f=g.GetComponentInChildren<MeshFilter>();var verts=Vertices(src);var local=verts.Select(v=>g.transform.InverseTransformPoint(f.transform.TransformPoint(v))).ToArray();float bottom=local.Min(v=>v.y);var keep=new List<int>();Vector2[] uv;
   using(var raw=MeshUtility.AcquireReadOnlyMeshData(src.sharedMesh)){var d=raw[0];using(var ix=new NativeArray<int>(d.GetSubMesh(0).indexCount,Allocator.Temp)){d.GetIndices(ix,0);for(int k=0;k<ix.Length;k+=3)if(local[ix[k]].y>=bottom+7.99f&&local[ix[k+1]].y>=bottom+7.99f&&local[ix[k+2]].y>=bottom+7.99f)keep.AddRange(new[]{ix[k],ix[k+1],ix[k+2]});}using(var a=new NativeArray<Vector2>(d.vertexCount,Allocator.Temp)){d.GetUVs(0,a);uv=a.ToArray();}}
   Check(keep.Count>0,"natural upper surface "+g.name);var used=keep.Distinct().OrderBy(i=>i).ToArray();var remap=used.Select((id,i)=>(id,i)).ToDictionary(x=>x.id,x=>x.i);var mesh=new Mesh{name="Natural mountain | original slopes, lower wall removed"};mesh.vertices=used.Select(i=>verts[i]).ToArray();mesh.uv=used.Select(i=>uv[i]).ToArray();mesh.triangles=keep.Select(i=>remap[i]).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath(folder+"/Natural_"+g.name.Split('|')[0].Trim().Replace(' ','_')+".asset"));f.sharedMesh=mesh;
   var pos=g.transform.position;pos.y=0;g.transform.position=pos;float seat=float.MaxValue;var rim=used.Where(i=>local[i].y<=bottom+8.1f).ToArray();Check(rim.Length>=32,"complete natural rim "+g.name);
   foreach(int i in rim){var w=f.transform.TransformPoint(verts[i]);Check(Mathf.Abs(w.x)<499&&Mathf.Abs(w.z)<499,"mountain footprint inside terrain "+g.name+" "+w);seat=Mathf.Min(seat,Ground(w)-w.y-.8f);}g.transform.position+=Vector3.up*seat;
   foreach(int i in rim){var w=f.transform.TransformPoint(verts[i]);Check(w.y<=Ground(w)-.79f,"buried open rim "+g.name);}int visible=used.Count(i=>{var w=f.transform.TransformPoint(verts[i]);return w.y>Ground(w)+1;});Check(visible>=3,"visible mountain slopes "+g.name);f.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;
   return g.name+" | radius="+new Vector2(pos.x,pos.z).magnitude+" | triangles="+src.sharedMesh.subMeshCount+":"+keep.Count/3+" | removed="+(entry.triangles-keep.Count/3)+" | seatedY="+seat+" | rim="+rim.Length+" | visible vertices="+visible;
  }

