   string pine=Hash("Assets/Scenes/Pinefall.unity"),profile=Hash(SaveStore.PathName),profileBak=Hash(SaveStore.PathName+".bak"),seedPath=AssetDatabase.GetAssetPath(All<SnowField>(scene).Single().seed),seedHash=Hash(seedPath);var folder=AssetDatabase.GenerateUniqueAssetPath("Assets/Snowglow/Levels/TheAlps/InsetHillBelt");Directory.CreateDirectory(folder);AssetDatabase.Refresh();
   try{
    var f=terrainMesh.GetComponent<MeshFilter>();var old=f.sharedMesh;var v=Vertices(f);var before=(Vector3[])v.Clone();var world=before.Select(a=>f.transform.TransformPoint(a)).ToArray();var pinned=new bool[v.Length];using(var raw=MeshUtility.AcquireReadOnlyMeshData(old))using(var ix=new NativeArray<int>(raw[0].GetSubMesh(0).indexCount,Allocator.Temp)){raw[0].GetIndices(ix,0);for(int i=0;i<ix.Length;i+=3){var a=world[ix[i]];var b=world[ix[i+1]];var c=world[ix[i+2]];if(Mathf.Min(a.x,b.x,c.x)<=245&&Mathf.Max(a.x,b.x,c.x)>=-245&&Mathf.Min(a.z,b.z,c.z)<=245&&Mathf.Max(a.z,b.z,c.z)>=-245)pinned[ix[i]]=pinned[ix[i+1]]=pinned[ix[i+2]]=true;}}var samples=new List<(Vector3,float)>();for(int z=-240;z<=240;z+=24)for(int x=-240;x<=240;x+=24){var at=new Vector3(x,0,z);samples.Add((at,Ground(at)));}
    int changed=0;for(int i=0;i<v.Length;i++){var w=f.transform.TransformPoint(v[i]);float r=Mathf.Max(Mathf.Abs(w.x),Mathf.Abs(w.z));if(pinned[i]||r<=270.001f||w.y<SnowField.Ground-.02f)continue;float lookup=Mathf.Min(499.999f,270+(r-270)*(230f/80f));var at=new Vector3(w.x*lookup/r,0,w.z*lookup/r);w.y=Ground(at);v[i]=f.transform.InverseTransformPoint(w);changed++;}
    var mesh=new Mesh{name="Alps inset hill belt | town triangles pinned, outer plateau from350",indexFormat=old.indexFormat};mesh.vertices=v;using(var raw=MeshUtility.AcquireReadOnlyMeshData(old)){var d=raw[0];using(var ix=new NativeArray<int>(d.GetSubMesh(0).indexCount,Allocator.Temp)){d.GetIndices(ix,0);mesh.SetTriangles(ix.ToArray(),0);}using(var uv=new NativeArray<Vector2>(d.vertexCount,Allocator.Temp)){d.GetUVs(0,uv);mesh.uv=uv.ToArray();}}mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/InsetTerrain.asset");f.sharedMesh=mesh;terrainMesh.sharedMesh=mesh;Physics.SyncTransforms();foreach(var sample in samples)Check(Mathf.Abs(Ground(sample.Item1)-sample.Item2)<.002f,"central town terrain retained "+sample.Item1);
    var query=All<Terrain>(scene).Single();var data=UnityEngine.Object.Instantiate(query.terrainData);var h=new float[257,257];for(int z=0;z<257;z++)for(int x=0;x<257;x++){var at=new Vector3(Mathf.Clamp(x/256f*1000-500,-499.999f,499.999f),0,Mathf.Clamp(z/256f*1000-500,-499.999f,499.999f));h[z,x]=(Ground(at)-query.transform.position.y)/data.size.y;}data.SetHeights(0,0,h);AssetDatabase.CreateAsset(data,folder+"/TerrainQuery.asset");query.terrainData=data;query.GetComponent<TerrainCollider>().terrainData=data;
    var report=new List<string>();foreach(var p in list){var g=p.gameObject;var position=g.transform.position;var direction=new Vector3(position.x,0,position.z).normalized;var bounds=WorldBounds(g);float distance=float.MaxValue;float target=465;
     if(Mathf.Abs(direction.x)>.00001f)distance=Mathf.Min(distance,(direction.x>0?target-(bounds.max.x-position.x):-target-(bounds.min.x-position.x))/direction.x);
     if(Mathf.Abs(direction.z)>.00001f)distance=Mathf.Min(distance,(direction.z>0?target-(bounds.max.z-position.z):-target-(bounds.min.z-position.z))/direction.z);
