     foreach(int i in rim){var w=mf.transform.TransformPoint(verts[i]);Check(w.y<=Ground(w)-.79f,"no floating rim "+g.name);}bounds=WorldBounds(g);float margin=Mathf.Min(500-bounds.max.x,500+bounds.min.x,500-bounds.max.z,500+bounds.min.z);Check(margin>34.98f&&margin<35.02f,"35m outside terrain margin "+g.name);Check(Mathf.Max(Mathf.Abs(g.transform.position.x),Mathf.Abs(g.transform.position.z))>350,"mountain centre beyond hill belt "+g.name);report.Add(g.name+" | centre="+g.transform.position+" | outside margin="+margin+"m | original504-triangle mesh retained");
    }
