    File.WriteAllText(log+"/Validation.txt","PASS: hill relief compressed into square-radius270-350m with triangles touching inner245m pinned, elevated outer shelf350-500m; central441 ground samples unchanged. Original terrain vertex/triangle count, footprint, UVs and vertical cut walls retained in new derivative. Physical terrain mesh and hidden257 camera query updated together.16 mountains behind hill belt, every outside margin35m and every open rim >=.8m buried. No mountain mesh modification or stems. Saved/reopened, scene/19 snow and static access checks passed. Review32 mountain captures and overview. Pinefall/profile/snow preserved. Changed terrain vertices="+changed+". No Play/device acceptance.\n"+string.Join("\n",report));
   }catch{if(SceneManager.GetActiveScene().isDirty)EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),log+"/Failed-unsaved-"+stamp+".unity",true);File.Copy(backup,PathName,true);AssetDatabase.ImportAsset(PathName,ImportAssetOptions.ForceUpdate);EditorSceneManager.OpenScene(PathName);throw;}
