  public static void FixMountainBases(){
   const string log="Logs/AlpsMountainRevision";Directory.CreateDirectory(log);scene=SceneManager.GetActiveScene();Check(scene.path==PathName&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Alps, stop Play");string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");if(scene.isDirty)Check(EditorSceneManager.SaveScene(scene,log+"/Unsaved-before-"+stamp+".unity",true),"backup unsaved");Check(!scene.isDirty,"save manual scene edits first; unsaved copy preserved");var list=All<CatalogPlacement>(scene).Where(p=>p.assetId.StartsWith("alps-rebuild-mountain_")).OrderBy(p=>p.name).ToArray();Check(list.Length==16,"sixteen mountain placements");Check(list.All(p=>p.GetComponentInChildren<MeshFilter>().sharedMesh.GetIndexCount(0)!=1512),"already corrected; do not move again");string backup=log+"/Before-"+stamp+".unity";File.Copy(PathName,backup);string pine=Hash("Assets/Scenes/Pinefall.unity"),profile=Hash(SaveStore.PathName),profileBak=Hash(SaveStore.PathName+".bak");string seedPath=AssetDatabase.GetAssetPath(All<SnowField>(scene).Single().seed),seedHash=Hash(seedPath);var folder=AssetDatabase.GenerateUniqueAssetPath("Assets/Snowglow/Levels/TheAlps/NaturalMountains");Directory.CreateDirectory(folder);AssetDatabase.Refresh();
   try{terrainMesh=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-terrainbase").GetComponentInChildren<MeshCollider>();var report=new List<string>();foreach(var p in list){var at=p.transform.position;float radius=new Vector2(at.x,at.z).magnitude;at.x*= (radius+25)/radius;at.z*= (radius+25)/radius;p.transform.position=at;report.Add(NaturalMountain(p.gameObject,folder));}Physics.SyncTransforms();Validate(scene);AssetDatabase.SaveAssets();Check(EditorSceneManager.SaveScene(scene),"save natural mountains");scene=EditorSceneManager.OpenScene(PathName);Validate(scene);Audit();Capture(scene);MountainViews(scene,log);EditorSceneManager.OpenScene(PathName);Check(Hash("Assets/Scenes/Pinefall.unity")==pine&&Hash(SaveStore.PathName)==profile&&Hash(SaveStore.PathName+".bak")==profileBak&&Hash(seedPath)==seedHash,"protected scene/profile/snow preservation");File.WriteAllText(log+"/Validation.txt","PASS:16 mountains moved25m outward (395 to420m); source-derived lower wall/bottom triangles deleted and original sloping surface seated with rim >=.8m under terrain. No rim stretched. Native save/reopen, scene/19 snow checks and static road access passed. Review32 native mountain views plus overview. Pinefall/profile/snow unchanged. No Play/device acceptance.\n"+string.Join("\n",report));}
