  static void MountainViews(Scene s,string log){var g=new GameObject("Temporary mountain inspection camera");SceneManager.MoveGameObjectToScene(g,s);var cam=g.AddComponent<Camera>();cam.CopyFrom(All<CameraRig>(s).Single().view);cam.enabled=false;cam.orthographic=false;cam.fieldOfView=55;cam.layerCullDistances=new float[32];cam.useOcclusionCulling=false;var rt=RenderTexture.GetTemporary(1280,720,24);var old=RenderTexture.active;try{cam.targetTexture=rt;int index=0;foreach(var p in All<CatalogPlacement>(s).Where(p=>p.assetId.StartsWith("alps-rebuild-mountain_")).OrderBy(p=>p.name)){var b=WorldBounds(p.gameObject);var radial=new Vector3(p.transform.position.x,0,p.transform.position.z).normalized;for(int side=0;side<2;side++){var dir=Quaternion.Euler(0,side*65,0)*radial;var at=b.center-dir*Mathf.Max(b.size.x,b.size.z)*1.65f;at.x=Mathf.Clamp(at.x,-490,490);at.z=Mathf.Clamp(at.z,-490,490);at.y=Mathf.Max(Ground(at)+20,b.min.y+18);cam.transform.position=at;cam.transform.LookAt(b.center);cam.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(log+"/Mountain_"+index.ToString("D2")+"_"+side+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}index++;}}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(g);}}
  static GameObject Borrow(CatalogPlacement template,Transform parent,string name,Vector3 at,float yaw,float scale=1){var g=UnityEngine.Object.Instantiate(template.gameObject,parent);g.name=name;g.transform.SetPositionAndRotation(at,Quaternion.Euler(0,yaw,0));g.transform.localScale=template.transform.lossyScale*scale;g.GetComponent<CatalogPlacement>().placementId="alps-rebuild-"+name.Replace(' ','-').ToLowerInvariant();foreach(var text in g.GetComponentsInChildren<TextMesh>(true))text.text=text.text.Replace("PINEFALL","THE ALPS").Replace("Pinefall","The Alps");g.SetActive(true);if(template.assetId=="four-bay-snow-garage"||template.assetId=="snow-machinery-fuel-station"||template.assetId=="snow-disposal-yard"){var pos=g.transform.position;pos.y=Ground(pos);g.transform.position=pos;}else Seat(g);return g;}
  static void Facilities(CatalogPlacement[] source){CatalogPlacement Find(string id)=>source.Single(p=>p.placementId==id);Borrow(Find("pinefall-garage"),facilities,"Snow garage | west-facing doors",new Vector3(-79,0,-103),270);Borrow(Find("pinefall-fuel-station"),facilities,"Fuel station | west-facing pumps",new Vector3(-109,0,-80),270);Borrow(Find("pinefall-disposal-yard"),facilities,"Snow disposal yard | south entrance",new Vector3(94,0,-85),180,1.3f);Pad("Garage manoeuvring forecourt",new Vector3(-97,0,-94),40,45);Pad("Fuel manoeuvring apron",new Vector3(-118,0,-88),20,28);Pad("Visitor parking",new Vector3(92,0,27),40,42);Pad("Tell square | open central plaza",new Vector3(18,0,25),32,34);}
  static void Furniture(CatalogPlacement[] source){var lamps=source.Where(p=>(p.assetId??"").StartsWith("alpine-street-light-")).GroupBy(p=>p.assetId).Select(g=>g.First()).Where(p=>!p.assetId.EndsWith("-06")).ToArray();int id=0;foreach(var route in plan.roads.Take(9)){for(int i=18;i<route.points.Length-1;i+=40){var p=route.points[i].V;var dir=(route.points[Mathf.Min(i+1,route.points.Length-1)].V-route.points[i-1].V).normalized;var at=p+Vector3.Cross(Vector3.up,dir)*(route.width*.5f+2);if(buildings.GetComponentsInChildren<Collider>().Any(c=>c.bounds.SqrDistance(new Vector3(at.x,c.bounds.center.y,at.z))<9))continue;Borrow(lamps[id%lamps.Length],furniture,"Street lamp "+(++id).ToString("D2"),at,225);}}
   var signs=source.Where(p=>(p.assetId??"").StartsWith("alpine-sign-")).GroupBy(p=>p.assetId).Select(g=>g.First()).ToArray();foreach(var spec in new[]{("Snow depot board",new Vector3(-113,0,-67),"SNOW DEPOT"),("Fuel and repair board",new Vector3(-132,0,-73),"FUEL + REPAIR"),("Disposal board",new Vector3(77,0,-112),"SNOW DISPOSAL"),("Town square board",new Vector3(-9,0,22),"TELL SQUARE"),("Northern village board",new Vector3(115,0,184),"THE ALPS")}){var template=signs.First(p=>p.assetId=="alpine-sign-01");var g=Borrow(template,furniture,spec.Item1,spec.Item2,225);foreach(var t in g.GetComponentsInChildren<TextMesh>(true))t.text=spec.Item3;}
  }
  static float RoadDistance(Vector3 at){float best=float.MaxValue;foreach(var r in plan.roads)for(int i=1;i<r.points.Length;i++){var a=r.points[i-1].V;var b=r.points[i].V;var delta=b-a;float u=Mathf.Clamp01(Vector3.Dot(at-a,delta)/Mathf.Max(.00001f,delta.sqrMagnitude));best=Mathf.Min(best,Vector3.Distance(at,a+u*delta)-r.width*.5f);}return best;}
  static void Snow(PrototypeSession session){var field=session.Snow;var seed=ScriptableObject.CreateInstance<SnowSeed>();seed.name="Rebuilt Alps independent road snow";seed.grid=new SnowVolumeGrid{authoredLayoutVersion=SnowField.CurrentLayoutVersion};var laneMask=new bool[seed.grid.depth.Length];foreach(var route in plan.roads)for(int k=1;k<route.points.Length;k++){var a=route.points[k-1].V;var b=route.points[k].V;float radius=route.width*.5f;int x0=Mathf.Clamp(Mathf.FloorToInt((Mathf.Min(a.x,b.x)-radius+128)/SnowVolumeGrid.Cell),0,SnowVolumeGrid.Size-1),x1=Mathf.Clamp(Mathf.CeilToInt((Mathf.Max(a.x,b.x)+radius+128)/SnowVolumeGrid.Cell),0,SnowVolumeGrid.Size-1),z0=Mathf.Clamp(Mathf.FloorToInt((Mathf.Min(a.z,b.z)-radius+128)/SnowVolumeGrid.Cell),0,SnowVolumeGrid.Size-1),z1=Mathf.Clamp(Mathf.CeilToInt((Mathf.Max(a.z,b.z)+radius+128)/SnowVolumeGrid.Cell),0,SnowVolumeGrid.Size-1);var delta=b-a;for(int iz=z0;iz<=z1;iz++)for(int ix=x0;ix<=x1;ix++){int index=iz*SnowVolumeGrid.Size+ix;var at=new Vector3(seed.grid.X(index),0,seed.grid.Z(index));float u=Mathf.Clamp01(Vector3.Dot(at-a,delta)/Mathf.Max(.00001f,delta.sqrMagnitude));if((at-a-u*delta).sqrMagnitude<radius*radius)laneMask[index]=true;}}for(int i=0;i<seed.grid.depth.Length;i++){float x=seed.grid.X(i),z=seed.grid.Z(i);bool venue=Enumerable.Range(0,3).Any(k=>CareerSnowState.Inside(SnowField.ContractBounds(k),x,z));bool lane=laneMask[i];bool parking=x>72&&x<112&&z>6&&z<48;bool clear=x>-140&&x<-60&&z>-126&&z<-68||x>70&&x<128&&z>-117&&z<-60;bool blocked=Physics.CheckBox(new Vector3(x,SnowField.Ground+.85f,z),new Vector3(.22f,.65f,.22f),Quaternion.identity,1,QueryTriggerInteraction.Ignore);seed.grid.blocked[i]=blocked;seed.grid.depth[i]=(lane||venue||parking)&&!clear&&!blocked&&!SnowField.DepotAccessStartsClear(x,z)?.24f:0;seed.grid.credit[i]=seed.grid.depth[i];}seed.grid.initialVolume=seed.grid.Total();AssetDatabase.CreateAsset(seed,Root+"/SnowSeed.asset");field.seed=seed;field.RebuildResolution(seed);SnowMeshAssets.SaveChunks(field,seed);}
