    var world=Group(Marker,null);terrainGroup=Group("01 Terrain",world);mountains=Group("02 Mountains",world);roads=Group("03 Roads | connected straight and curved streets",world);buildings=Group("04 Buildings | 70 readable Alpine homes",world);landmarks=Group("05 Landmarks",world);facilities=Group("06 Facilities | open manoeuvring yards",world);furniture=Group("07 Street furniture",world);var systems=Group("08 Gameplay | fresh Pinefall systems and fleet",null);foreach(var g in scene.GetRootGameObjects().Where(g=>g!=world.gameObject&&g!=systems.gameObject&&!templates.Any(p=>p.gameObject==g)).ToArray())g.transform.SetParent(systems,false);
