PathName,Log+"/Built-before-camera.unity",true);File.WriteAllText(Log+"/Stage.txt","Saved/reopened; capturing the real gameplay isometric camera at every home and facility.");Capture(scene);EditorSceneManager.OpenScene(PathName);Check(Hash("Assets/Scenes/Pinefall.unity")==pine&&Hash(SaveStore.PathName)==profile&&Hash(SaveStore.PathName+".bak")==profileBak,"Pinefall and real save preservation");File.WriteAllText(Log+"/SceneBuild.txt","PASS: supplied-terrain rebuild saved/reopened.70 buildings,16 mountains, two imported landmarks, Pinefall facilities/signs/lamps, connected street network, fresh systems and independent snow. Previous Alps backup "+backup+". Pinefall/profile bytes preserved. Native gameplay-camera captures generated; review all captures and clearance checks before claiming completion. No Play or device acceptance.\n");var view=SceneView.lastActiveSceneView;if(view){view.LookAt(new Vector3(0,30,0),Quaternion.Euler(41,45,0),650);view.Repaint();}
