  public static void Validate(Scene s){Check(s.path==PathName,"Alps path");Check(All<Transform>(s).Any(t=>t.name==Marker),"new scene marker");var homes=All<Transform>(s).Single(t=>t.name.StartsWith("04 Buildings")).Cast<Transform>().ToArray();Check(homes.Length==70,"70 buildings");foreach(var h in homes){Check(h.GetComponentsInChildren<Collider>().Length==1&&h.GetComponentInChildren<BoxCollider>(),"one home collider "+h.name);Check(Vector3.Dot(h.forward,new Vector3(-1,0,-1).normalized)>.99f,"isometric-visible front "+h.name);}for(int i=0;i<homes.Length;i++)for(int j=i+1;j<homes.Length;j++){var a=WorldBounds(homes[i].gameObject);var b=WorldBounds(homes[j].gameObject);Check(!(a.min.x<b.max.x+5.8f&&a.max.x>b.min.x-5.8f&&a.min.z<b.max.z+5.8f&&a.max.z>b.min.z-5.8f),"readable spacing "+homes[i].name+" / "+homes[j].name);}SceneValidation.Validate(s);AlpsTownAuthoring.Validate(s);MechanicsChecks.Run();File.WriteAllText(Log+"/SceneChecks.txt","PASS:70 homes, single boxes, southwest fronts, >=5.8m projected-axis lot gap; required gameplay/UI/fleet/terrain/snow contracts and19 ledger checks. Additional road connectivity, full vehicle routes and camera visibility review remain required.\n");}




  public static void Finish(){
   var s=SceneManager.GetActiveScene();Check(s.path==PathName&&!s.isDirty&&!EditorApplication.isPlaying,"clean Alps for final material/access pass");File.Copy(PathName,Log+"/Before-finish.unity",true);
   terrainMesh=All<CatalogPlacement>(s).Single(p=>p.assetId=="alps-rebuild-terrainbase").GetComponentInChildren<MeshCollider>();
   var board=All<Transform>(s).Single(t=>t.name=="Snow depot board");board.position=new Vector3(-120,Ground(new Vector3(-120,0,-105)),-105);
   var snow=All<SnowField>(s).Single();var mat=snow.palette.snow;int changed=0;
   foreach(var placement in All<CatalogPlacement>(s).Where(p=>p.assetId.StartsWith("alps-rebuild-")))foreach(var r in placement.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="SnowCover")){r.sharedMaterial=mat;changed++;}
   foreach(string path in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Snowglow/Catalog/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>System.IO.Path.GetFileName(p).StartsWith("alps-rebuild-"))){var root=PrefabUtility.LoadPrefabContents(path);try{foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="SnowCover"))r.sharedMaterial=mat;PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}}
   Physics.SyncTransforms();var revised=UnityEngine.Object.Instantiate(snow.seed);for(int i=0;i<revised.grid.blocked.Length;i++)revised.grid.blocked[i]=Physics.CheckBox(new Vector3(revised.grid.X(i),SnowField.Ground+.85f,revised.grid.Z(i)),new Vector3(.22f,.65f,.22f),Quaternion.identity,1,QueryTriggerInteraction.Ignore);string folder=System.IO.Path.GetDirectoryName(AssetDatabase.GetAssetPath(snow.seed));AssetDatabase.CreateAsset(revised,AssetDatabase.GenerateUniqueAssetPath(folder+"/FinalObstacleSeed.asset"));snow.seed=revised;EditorUtility.SetDirty(snow);AssetDatabase.SaveAssets();Validate(s);Check(EditorSceneManager.SaveScene(s),"final scene save");EditorSceneManager.OpenScene(PathName);Audit();Capture(SceneManager.GetActiveScene());EditorSceneManager.OpenScene(PathName);File.WriteAllText(Log+"/Finish.txt","Saved/reopened: depot board outside service route; "+changed+" removable snow covers share existing white/cyan toon material, including reusable prepared prefabs. Source Blender/FBX/UVs unchanged. Snow depth and credit unchanged.");
  }
